INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5312bc23-44bf-5058-9635-360acd11cb1b'::uuid, 'f1b4bfc2-d305-58ee-b23f-092971f36733'::uuid, 'Apartment Painting Project 2', 'En collaboration avec le client, nous avons appliqué les couleurs et les finitions souhaitées, en respectant parfaitement sa vision et ses attentes.', '["https://lechantier.ma/uploads/media/06692ead8c26.webp", "https://lechantier.ma/uploads/media/f9ddac342417.webp", "https://lechantier.ma/uploads/media/a155664eaa52.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/06692ead8c26.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.3.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('87a09ec5-765f-5a70-85f8-9b00fbb1e60e'::uuid, 'f1b4bfc2-d305-58ee-b23f-092971f36733'::uuid, 'Apartment Painting Project', 'Cet appartement a été peint entièrement à partir de zéro, en partant de surfaces brutes ou non finies pour le transformer en un espace moderne, élégant et accueillant. Notre équipe a pris en charge toutes les étapes du projet, de la préparation des surfaces et l’application des sous-couches jusqu’aux finitions finales. Chaque mur, chaque plafond et chaque détail ont été réalisés avec précision afin d’obtenir un résultat durable et de haute qualité.', '["https://lechantier.ma/uploads/media/9aac330e6f12.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/9aac330e6f12.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.3.2' LIMIT 1));
