INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a51477fc-6208-5839-8793-1ad9a97bf238'::uuid, '72e04bbc-018a-5d49-bc92-24a1d5f2a044'::uuid, 'Habillage complet pour appartement', 'Dans le cadre de ce projet résidentiel, notre équipe a réalisé l’habillage intégral des murs d’un appartement situé à Marrakech, en combinant esthétique raffinée, matériaux nobles et fonctionnalité sur mesure.', '["https://lechantier.ma/uploads/media/9d817deefdcd.webp", "https://lechantier.ma/uploads/media/bc78e1a35bfa.webp", "https://lechantier.ma/uploads/media/58f6635cf97e.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/9d817deefdcd.webp', 'Mohammedia', (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('09f65c24-114e-5fcb-b42a-5c1928763f0f'::uuid, '72e04bbc-018a-5d49-bc92-24a1d5f2a044'::uuid, 'Pack de 3 (salon, entrée, chambre)', 'Ce projet sur mesure incarne l’élégance et le savoir-faire artisanal à travers l’habillage complet de trois espaces clés d’un appartement à Casablanca : l’entrée, le salon, et la chambre à coucher. Chaque zone a été pensée pour allier esthétique contemporaine, fonctionnalité, et matériaux nobles.', '["https://lechantier.ma/uploads/media/10429f826ef5.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/10429f826ef5.webp', 'Mohammedia', (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1));
