INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2d9570a8-38a0-539a-bd7f-ce09b5205a78'::uuid, '0a9b4c29-ae38-55ec-b447-05a847172a9b'::uuid, 'أكادير سيتي سلام', 'هاد البرطمة خدمت فيها صباغة ستيكو بهاد الطريقة لي في الصور طلعت مزيانة خدمتها برشكة أركول صباغة لي مزيانة كتعطي منظر زوينة و هي ضمن صباغات العنبرة المطلوبة مؤخرا خصوصا في المنازل و الفيلات .لبغا نخدم له بحال هاد الأنواع من الديكورات مرحبا و بثمن مناسب و جميع الديكورات الاخرين المخايل و صابلي و صباغات الاكي المائية لكتعطي منظر بريو رائع', '["https://lechantier.ma/uploads/media/bdae858964e0.webp", "https://lechantier.ma/uploads/media/e547ad840c51.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/bdae858964e0.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '3.3.2' LIMIT 1));
